@import "tailwindcss";

:root { --ink:#16352f; --muted:#657772; --paper:#fffdf8; --line:#e6ebe7; --teal:#167d6d; --teal-dark:#105e53; --orange:#ee7b4b; --cream:#f3f0e8; }
* { box-sizing:border-box; }
html { scroll-behavior:smooth; }
body { margin:0; background:#f6f7f3; color:var(--ink); font-family:"Microsoft YaHei","PingFang SC",Arial,sans-serif; }
button,input,select,textarea { font:inherit; }
button,a { -webkit-tap-highlight-color:transparent; }
button { cursor:pointer; }
.brand { display:flex; align-items:center; gap:10px; color:var(--ink); font-weight:800; text-decoration:none; letter-spacing:.02em; }
.brand-mark { display:grid; place-items:center; width:34px; height:34px; border-radius:11px 11px 11px 4px; color:white; background:var(--teal); box-shadow:0 6px 14px #167d6d22; }

/* Landing */
.landing { min-height:100vh; background:linear-gradient(180deg,#f5f3e9 0,#faf9f5 58%,#f1f6f2 100%); overflow:hidden; }
.landing-nav { height:76px; max-width:1180px; margin:auto; padding:0 30px; display:flex; align-items:center; justify-content:space-between; }
.landing-nav>a { color:#50655f; text-decoration:none; font-size:14px; }
.hero { max-width:1180px; min-height:650px; padding:76px 30px 100px; margin:auto; display:grid; grid-template-columns:1.02fr .98fr; gap:90px; align-items:center; position:relative; }
.hero:before { content:""; position:absolute; width:450px; height:450px; border-radius:50%; background:#dcebe2; right:-210px; top:0; filter:blur(1px); opacity:.55; }
.eyebrow { display:inline-flex; padding:8px 13px; border-radius:999px; background:#e4eee7; color:var(--teal-dark); font-size:13px; font-weight:700; letter-spacing:.08em; }
.hero h1 { margin:24px 0 22px; font-size:68px; line-height:1.08; letter-spacing:-.055em; font-weight:900; color:#1b332e; }
.hero h1 span { color:var(--teal); position:relative; }
.hero h1 span:after { content:""; position:absolute; height:8px; background:#efb44a55; bottom:0; left:3%; right:0; border-radius:50%; transform:rotate(-1deg); }
.hero-copy>p { max-width:570px; font-size:18px; line-height:1.8; color:#61736e; }
.hero-actions { display:flex; align-items:center; gap:20px; margin-top:34px; }
.primary-btn { padding:15px 27px; background:var(--teal); border-radius:13px; color:white; font-weight:800; text-decoration:none; box-shadow:0 12px 28px #126f6130; }
.hero-actions span { color:#71817d; font-size:13px; }
.hero-proof { margin-top:30px; color:#77857f; font-size:14px; }
.hero-proof b { color:var(--ink); font-size:20px; margin:0 4px; }
.hero-panel { position:relative; z-index:1; background:#fffefa; border:1px solid #e0e8e2; padding:25px; border-radius:26px; box-shadow:0 30px 80px #41564d1c; transform:rotate(1.5deg); }
.hero-panel:before { content:"班级工作台"; position:absolute; top:-34px; right:24px; padding:11px 20px; color:#6d775f; background:#f4c961; font-weight:800; border-radius:8px 8px 0 0; transform:rotate(2deg); }
.panel-head { display:flex; justify-content:space-between; align-items:center; margin-bottom:20px; }
.panel-head span { font-weight:800; font-size:18px; }.panel-head small { color:#d76439; background:#fff0e9; padding:7px 10px; border-radius:8px; }
.mini-stats { display:grid; grid-template-columns:repeat(3,1fr); background:#edf5f1; border-radius:16px; padding:18px 8px; margin-bottom:18px; }
.mini-stats div { display:grid; text-align:center; gap:4px; border-right:1px solid #dbe6e0; }.mini-stats div:last-child { border:0; }.mini-stats b{font-size:25px}.mini-stats span{color:#72827c;font-size:12px}
