.section-heading { text-align:center; margin-bottom:50px; }.section-heading span{color:var(--orange);font-size:13px;font-weight:800;letter-spacing:.15em}.section-heading h2{font-size:36px;margin:12px 0;letter-spacing:-.04em}
.feature-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:16px; }.feature-grid article{position:relative;padding:30px;background:#fff;border:1px solid #e6eae5;border-radius:18px;min-height:180px}.feature-grid article>span{position:absolute;right:20px;top:16px;color:#dfe8e3;font-size:36px;font-weight:900}.feature-grid h3{font-size:19px;margin:38px 0 10px}.feature-grid p{color:#788681;line-height:1.7;font-size:14px}
